var builder=WebApplication.CreateBuilder(args);builder.Services.AddOpenApi();builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins("http://localhost:3100").AllowAnyHeader().AllowAnyMethod()));var app=builder.Build();app.UseCors();app.MapOpenApi();app.MapPost("/api/auth/login",(Login login,IConfiguration c)=>login.Email==c["REVENDAPRO_ADMIN_EMAIL"]&&login.Password==c["REVENDAPRO_ADMIN_PASSWORD"]?Results.Ok(new{data=new{userCode="local-admin",name="Administrador",email=login.Email,permissions=new[]{"dashboard.view","users.manage","roles.manage"}}}):Results.Unauthorized());app.MapGet("/health",()=>Results.Ok(new{status="ok"}));app.Run();record Login(string Email,string Password);
